  static const lessons=<SpanishB2Lesson>[
    SpanishB2Lesson(unit:1,number:1,title:"Ojalá cambiara la historia",titleAr:"التعبير عن الأمنية",grammar:"Ojalá + imperfecto de subjuntivo",grammarAr:"الأماني غير المتحققة أو البعيدة",grammarHelpAr:"بعد ojalá نستخدم الماضي الناقص من subjuntivo للتعبير عن أمنية يصعب تحقيقها الآن.",grammarExamples:<String>["Ojalá tuviera más tiempo.","Ojalá pudiéramos participar.","Ojalá la noticia fuera cierta.","Ojalá hablaras con el director.","Ojalá no hubiera tantos rumores.","Ojalá el archivo estuviera abierto.","Ojalá alguien explicara el problema.","Ojalá supiéramos la verdad."],grammarMistakes:<String>["Ojalá tengo más tiempo.","Ojalá nosotros podemos participar."],story:<String>["Una periodista llegó al archivo municipal para investigar una fotografía que circulaba por internet. Muchos vecinos afirmaban reconocer a la persona que aparecía en ella, pero sus testimonios no coincidían entre sí.","El archivero le mostró el documento original y explicó que faltaba una parte del registro. La periodista pensó que ojalá existiera una copia completa, porque podría aclarar el origen de la imagen.","Al entrevistar a los vecinos, descubrió que algunos recordaban hechos de distintas épocas. Un testigo reconoció que había repetido una historia sin comprobar nunca su fuente.","En lugar de publicar una explicación apresurada, la periodista comparó las fechas con otros documentos. Su editor aceptó retrasar el reportaje para evitar una conclusión engañosa.","Cuando finalmente salió el artículo, no ofrecía una respuesta definitiva, pero mostraba qué datos podían verificarse. Los lectores agradecieron aquella cautela poco habitual."]),
    SpanishB2Lesson(unit:1,number:2,title:"Era necesario que escucháramos",titleAr:"exigir un cambio en الماضي",grammar:"Era necesario que + imperfecto de subjuntivo",grammarAr:"الضرورة في الماضي",grammarHelpAr:"مع era necesario que نستخدم فعلًا في الماضي الناقص من subjuntivo لوصف أمر كان مطلوبًا.",grammarExamples:<String>["Era necesario que todos escucharan.","Era importante que revisáramos el informe.","Hacía falta que aclararas la fecha.","Era urgente que el portavoz respondiera.","Era conveniente que contrastaran los datos.","Era imprescindible que llegáramos a un acuerdo.","Era mejor que consultaras el archivo.","Era necesario que la reunión continuara."],grammarMistakes:<String>["Era necesario que todos escuchaban.","Era importante que nosotros revisamos el informe."],story:<String>["El consejo escolar reunió a familias y docentes para tratar el cierre de una biblioteca. La propuesta había provocado una controversia porque el barrio carecía de otros espacios de estudio gratuitos.","La directora explicó que era necesario que todos escucharan antes de votar. Una asociación había preparado cifras sobre el uso de la biblioteca, mientras varios vecinos aportaban experiencias personales.","El debate se complicó cuando aparecieron dos presupuestos diferentes. Para comparar correctamente los datos, el consejo pidió a los responsables que aclararan sus criterios.","Una profesora propuso mantener abierto el edificio durante un periodo de prueba. Su alternativa parecía viable, pero exigía que la comunidad colaborara y revisara los resultados.","Al terminar la reunión, nadie afirmó que el conflicto estuviera resuelto. Sin embargo, el grupo acordó analizar nuevas opciones con mayor transparencia."]),
    SpanishB2Lesson(unit:1,number:3,title:"Aunque resulte difícil",titleAr:"dos perspectivas sobre un hecho",grammar:"Aunque + indicativo o subjuntivo",grammarAr:"التمييز بين الواقع والاحتمال مع aunque",grammarHelpAr:"مع aunque نستعمل indicativo لحقيقة معروفة، وsubjuntivo لافتراض أو معلومة غير مؤكدة.",grammarExamples:<String>["Aunque llueve, salimos.","Aunque llueva, saldremos.","Aunque el informe es largo, resulta claro.","Aunque el informe sea largo, lo leeré.","Aunque conozco el barrio, consulto el mapa.","Aunque no se conozca la causa, investigaremos.","Aunque ya terminó, seguimos hablando.","Aunque parezca improbable, merece estudiarse."],grammarMistakes:<String>["Aunque lloverá mañana, saldremos.","Aunque sea una verdad que el informe es largo, resulta claro."],story:<String>["Una guía organizó una ruta cultural para mostrar lugares poco conocidos de la ciudad. Aunque el recorrido era corto, incluía edificios cuya historia resultaba difícil de reconstruir.","Algunos participantes dudaban de que mereciera la pena entrar en un archivo pequeño. La guía respondió que, aunque pareciera menos interesante que un museo famoso, contenía testimonios valiosos.","Durante la visita encontraron dos versiones diferentes sobre un antiguo puente. Una procedía de una crónica oficial y otra de una carta familiar conservada por un vecino.","La guía explicó por qué una fuente no debía rechazarse únicamente por ser personal. Animó al grupo a contrastar cada interpretación con documentos de la época.","Al final, los visitantes redactaron sus propias conclusiones. Aunque no llegaron a un acuerdo absoluto, aprendieron a expresar desacuerdos sin confundir hipótesis con hechos."]),
    SpanishB2Lesson(unit:1,number:4,title:"Si tuviera los datos",titleAr:"hipótesis del presente",grammar:"Si + imperfecto de subjuntivo + condicional",grammarAr:"الشرط الافتراضي في الحاضر",grammarHelpAr:"لوصف موقف غير حقيقي أو بعيد الاحتمال نستخدم si + imperfecto de subjuntivo ثم condicional.",grammarExamples:<String>["Si tuviera tiempo, investigaría más.","Si supiéramos la respuesta, la explicaríamos.","Si hubiera una copia, la consultaríamos.","Si fueras portavoz, ¿qué dirías?","Si la fuente fuera fiable, la citaría.","Si pudieran participar, aportarían ideas.","Si encontráramos pruebas, cambiaríamos la conclusión.","Si yo estuviera allí, escucharía a todos."],grammarMistakes:<String>["Si tendría tiempo, investigaría más.","Si sabemos la respuesta, la explicaríamos en una hipótesis irreal."],story:<String>["Una estudiante de periodismo preparaba un reportaje sobre una fábrica abandonada. Quería saber si el edificio podía convertirse en un espacio cultural, pero no encontraba información reciente sobre su estado.","En una reunión, su compañero dijo que si tuvieran los datos necesarios podrían comparar varios proyectos. Otra estudiante sugirió entrevistar a residentes antes de formular propuestas.","El equipo examinó antiguos presupuestos y descubrió que las cifras no incluían el coste de las reparaciones. Comprendieron que una alternativa atractiva no siempre era económicamente viable.","Mientras trabajaban, discutieron qué preguntas debían formular al ayuntamiento. Decidieron distinguir lo que sabían de aquello que todavía necesitaban comprobar.","Su reportaje terminó con diferentes escenarios posibles, no con una recomendación definitiva. La profesora destacó que reconocer la incertidumbre era una muestra de pensamiento crítico."]),
    SpanishB2Lesson(unit:1,number:5,title:"Habríamos llegado antes",titleAr:"posibilidades no realizadas",grammar:"Condicional compuesto",grammarAr:"ما كان يمكن أن يحدث",grammarHelpAr:"نستخدم habría + participio للتعبير عن نتيجة افتراضية أو posibilidad no realizada en el pasado.",grammarExamples:<String>["Habríamos llegado antes.","Yo habría publicado otra versión.","Ella habría revisado la noticia.","¿Habrías aceptado la propuesta?","No habrían podido entrar.","El director habría solicitado otro informe.","Habría sido una decisión arriesgada.","Los vecinos habrían apoyado la iniciativa."],grammarMistakes:<String>["Yo habría publica otra versión.","Ellos habría llegado antes."],story:<String>["Un equipo de documentalistas viajó a una comarca montañosa para entrevistar a personas mayores. Habían preparado una agenda cuidadosa, pero una avería retrasó el autobús durante varias horas.","La investigadora principal comentó que habrían llegado antes con otro transporte. Sin embargo, reconoció que nadie podía prever aquella avería y que culpar al conductor sería injusto.","Cuando llegaron, una de las entrevistadas ya había salido de viaje. Los documentalistas decidieron no inventar su testimonio y reorganizar el calendario para volver otro día.","Aprovecharon la tarde para consultar fotografías antiguas y conversar con el bibliotecario. Aquellos documentos ofrecieron información que no aparecía en las fuentes publicadas.","De regreso, el equipo revisó sus decisiones y explicó las limitaciones del proyecto. El documental final mostró tanto los hallazgos como las oportunidades perdidas."]),
    SpanishB2Lesson(unit:1,number:6,title:"Esperaba que hubieran respondido",titleAr:"expectativas anteriores",grammar:"Pluscuamperfecto de subjuntivo",grammarAr:"حدث كان مأمولًا قبل نقطة ماضية",grammarHelpAr:"نستخدم hubiera o hubiese + participio بعد أفعال التوقع والتقييم الماضية للإشارة إلى حدث سابق غير مؤكد.",grammarExamples:<String>["Esperaba que hubieran respondido.","Me alegró que hubieras venido.","Dudaba que lo hubieran publicado.","Era lógico que hubiésemos preguntado.","No creía que el rumor se hubiera extendido.","Ojalá hubieran conservado el archivo.","Temíamos que se hubiese perdido.","Me sorprendió que hubieran rectificado."],grammarMistakes:<String>["Esperaba que habían respondido.","Me alegró que tú has venido ayer."],story:<String>["Una investigadora regresó a su universidad después de visitar varios archivos locales. Esperaba que los expertos hubieran respondido a sus preguntas antes de una conferencia internacional.","Al revisar el correo descubrió que algunos documentos todavía no estaban disponibles. Una colega dudaba que la institución hubiera digitalizado los registros más antiguos.","La investigadora llamó al archivo para conocer los plazos reales. La empleada explicó que el equipo había tenido problemas técnicos y que necesitaba tiempo para resolverlos.","En la conferencia, la investigadora presentó los datos que podía verificar y reconoció las lagunas restantes. Rechazó utilizar un gráfico atractivo cuya procedencia no estaba clara.","Sus compañeros valoraron especialmente esa decisión. Entendieron que una investigación rigurosa debe explicar qué pruebas faltan y no solo qué resultados se han obtenido."]),
    SpanishB2Lesson(unit:1,number:7,title:"Si hubiéramos sabido la verdad",titleAr:"situaciones irreales pasadas",grammar:"Si + pluscuamperfecto de subjuntivo",grammarAr:"شرط مستحيل التحقق في الماضي",grammarHelpAr:"نستخدم si hubiera + participio ثم habría + participio لوصف شرط ماضٍ لم يحدث ونتيجته المفترضة.",grammarExamples:<String>["Si hubiéramos sabido la verdad, habríamos actuado antes.","Si hubiera llovido, habrían cancelado el acto.","Si me hubieras avisado, habría acudido.","Si el informe hubiera llegado, lo habríamos leído.","Si ella hubiera tenido pruebas, habría cambiado de idea.","Si hubieran escuchado, habrían evitado el conflicto.","Si hubiera sido posible, habríamos esperado.","Si no hubiéramos perdido el mapa, habríamos llegado."],grammarMistakes:<String>["Si habríamos sabido la verdad, habríamos actuado.","Si hubiera sabido, habría actuar antes."],story:<String>["Una asociación vecinal organizó una jornada para recuperar un jardín comunitario. Los voluntarios llegaron temprano, pero encontraron la entrada cerrada y el material almacenado en otro edificio.","El coordinador explicó que la reserva había sido modificada sin que el grupo recibiera el aviso. Algunas personas dijeron que, si lo hubieran sabido, habrían elegido otra fecha.","En vez de abandonar el proyecto, buscaron una alternativa en un parque cercano. Tuvieron que modificar el programa y reducir el número de actividades previstas.","Durante la tarde, los organizadores revisaron sus procedimientos de comunicación. Reconocieron que habían confiado demasiado en un único mensaje que nunca fue confirmado.","El encuentro terminó con nuevas propuestas para el futuro. Aprendieron que analizar errores pasados resulta útil cuando conduce a decisiones más responsables."]),
    SpanishB2Lesson(unit:1,number:8,title:"Me contó que viajaría",titleAr:"reported speech retrospectivo",grammar:"Estilo indirecto: condicional de futuro",grammarAr:"نقل المستقبل من نقطة زمنية ماضية",grammarHelpAr:"عندما ننقل توقعًا مستقبليًا قيل في الماضي، غالبًا يتحول viajaré إلى dijo que viajaría.",grammarExamples:<String>["Me dijo: «Viajaré». Luego me contó que viajaría.","Ana afirmó que regresaría pronto.","El guía anunció que comenzarían a las nueve.","El portavoz aseguró que explicarían la decisión.","Luis prometió que escribiría después.","Ella creyó que encontraría pruebas.","Nos dijeron que volverían mañana.","El profesor comentó que habría cambios."],grammarMistakes:<String>["Me contó que viajará el mes siguiente en ese pasado.","El portavoz dijo que explicarán ayer."],story:<String>["Una periodista entrevistó a un portavoz después de una reunión importante. Él afirmó que presentaría un informe completo la semana siguiente y respondería a las preguntas pendientes.","La periodista anotó sus palabras y comprobó el calendario oficial. Un compañero le advirtió de que las promesas no equivalían todavía a decisiones confirmadas.","Días después, el documento aún no se había publicado. Algunos medios afirmaban que el portavoz había incumplido el plazo, aunque el anuncio original era ambiguo.","La periodista revisó la grabación y distinguió entre una fecha concreta y una intención general. Decidió citar el fragmento completo para evitar interpretaciones engañosas.","Su artículo explicó qué se había prometido, qué seguía pendiente y por qué importaba esa diferencia. El editor valoró la precisión con que trató la información."]),
    SpanishB2Lesson(unit:1,number:9,title:"Buscamos a alguien que conozca",titleAr:"referentes desconocidos",grammar:"Relativas: subjuntivo con antecedente indefinido",grammarAr:"الموصول مع شخص أو شيء غير محدد",grammarHelpAr:"نستخدم subjuntivo بعد que إذا كنا نبحث عن شخص أو شيء غير معروف أو غير مؤكد الوجود.",grammarExamples:<String>["Busco a alguien que hable árabe.","Necesitamos un informe que sea fiable.","¿Conoces a alguien que pueda ayudar?","Quieren un lugar donde haya silencio.","No encuentro una fuente que confirme el dato.","Buscamos personas que tengan experiencia.","Necesito un guía que conozca la ciudad.","Queremos una solución que funcione."],grammarMistakes:<String>["Busco a alguien que habla árabe y no conozco a nadie.","Necesitamos un informe que es fiable pero no sabemos si existe."],story:<String>["Un museo local buscaba una persona que conociera la historia de un antiguo mercado. La directora quería preparar una exposición, pero apenas disponía de documentos sobre los comerciantes originales.","El equipo publicó una convocatoria para encontrar a alguien que pudiera explicar las tradiciones del barrio. Varias personas respondieron y ofrecieron fotografías familiares y recuerdos personales.","Una candidata había trabajado en el archivo municipal y conocía bien la zona. Sin embargo, reconoció que todavía existían preguntas que no podía responder con seguridad.","La directora decidió crear un pequeño grupo de investigación con diferentes especialistas. Prefería una explicación incompleta pero verificable a un relato emocionante sin fundamento.","La exposición abrió con documentos originales y testimonios identificados. Los visitantes pudieron conocer distintas perspectivas y formular sus propias preguntas."]),
    SpanishB2Lesson(unit:1,number:10,title:"Es posible que existan pruebas",titleAr:"duda frente a certeza",grammar:"Es posible que + subjuntivo",grammarAr:"الاحتمال وعدم الجزم",grammarHelpAr:"نستخدم subjuntivo بعد es posible que، أما es evidente que في الجمل المثبتة فيتبعه indicativo.",grammarExamples:<String>["Es posible que existan pruebas.","Puede que el testigo se equivoque.","Es posible que lleguen tarde.","No es seguro que el documento sea auténtico.","Es evidente que el archivo está cerrado.","Es posible que haya otra versión.","Quizá el informe contenga errores.","Es posible que necesitemos más datos."],grammarMistakes:<String>["Es posible que existen pruebas.","Es evidente que el documento sea auténtico en una afirmación."],story:<String>["Dos investigadores analizaron una noticia sobre un hallazgo arqueológico. El titular afirmaba que se había descubierto un objeto único, pero el informe original utilizaba expresiones mucho más prudentes.","Una especialista explicó que era posible que la pieza perteneciera a una época anterior. Todavía necesitaban estudiar los materiales y comparar otros objetos semejantes.","Un periodista preguntó por qué no podían ofrecer una conclusión definitiva. La investigadora aclaró que una hipótesis prometedora no debe presentarse como una certeza demostrada.","El equipo decidió publicar imágenes y métodos de análisis para facilitar la revisión de otros expertos. El proceso requería tiempo, pero aumentaba la credibilidad del trabajo.","Al terminar, el periodista cambió el titular por uno más preciso. Comprendió que informar con rigor también significa expresar correctamente la duda."]),
    SpanishB2Lesson(unit:2,number:1,title:"Para que todos participen",titleAr:"la participación comunitaria",grammar:"Para que + subjuntivo",grammarAr:"الغاية والهدف باستخدام para que",grammarHelpAr:"نستخدم para que + subjuntivo عندما نعبّر عن غرض فعل ويختلف فاعلا الفعلين.",grammarExamples:<String>["Publicamos las normas para que todos participen.","La asociación organiza talleres para que los jóvenes aprendan.","Explica el plan para que los vecinos lo entiendan.","He preparado un resumen para que tú lo leas.","Se ha instalado una rampa para que puedan entrar.","Hablaremos despacio para que nos comprendan.","El ayuntamiento financia el proyecto para que continúe.","Mandé la invitación para que vinieras."],grammarMistakes:<String>["Publicamos las normas para que todos participan.","La asociación organiza talleres para que los jóvenes aprender."],story:<String>["Una asociación cultural decidió abrir un espacio gratuito de debate en el barrio. Su objetivo era que jóvenes y mayores pudieran compartir ideas sin sentirse excluidos de las decisiones colectivas.","Los organizadores prepararon normas sencillas para que todos comprendieran el funcionamiento de las reuniones. También adaptaron el edificio para que las personas con movilidad reducida pudieran entrar con comodidad.","En el primer encuentro surgieron opiniones diferentes sobre los horarios. Algunos vecinos trabajaban por la noche, mientras otros necesitaban cuidar a sus familiares durante la tarde.","En vez de imponer una única solución, la asociación ofreció sesiones alternativas. Los participantes redactaron un resumen claro para que quienes no habían asistido pudieran expresar su opinión.","Al cabo de un mes aumentó la participación y mejoró la convivencia. Los organizadores comprendieron que crear oportunidades reales exige escuchar necesidades muy distintas."]),
    SpanishB2Lesson(unit:2,number:2,title:"Antes de que sea demasiado tarde",titleAr:"prevenir conflictos sociales",grammar:"Antes de que + subjuntivo",grammarAr:"قبل أن يحدث شيء",grammarHelpAr:"نستخدم antes de que + subjuntivo عندما نشير إلى فعل سيحدث لاحقًا أو لم يحدث بعد.",grammarExamples:<String>["Debemos actuar antes de que sea tarde.","Avísame antes de que lleguen los invitados.","Hablaré con ella antes de que se marche.","Revisaron el informe antes de que lo publicaran.","Conviene escuchar antes de que empiece el debate.","Vota antes de que termine el plazo.","Explica los riesgos antes de que decidan.","Lo solucionaremos antes de que empeore."],grammarMistakes:<String>["Debemos actuar antes de que es tarde.","Avísame antes de que llegan."],story:<String>["Los vecinos de un edificio antiguo observaron grietas cerca de la escalera principal. Al principio pensaron que no eran importantes, pero los problemas parecían aumentar después de cada tormenta.","Una residente propuso solicitar una inspección antes de que se produjera un accidente. Algunos propietarios se opusieron porque temían que las reparaciones fueran demasiado costosas.","La comunidad convocó una reunión y escuchó a un técnico independiente. El especialista explicó qué daños debían repararse con urgencia y cuáles podían esperar unos meses.","Para evitar rumores, los responsables distribuyeron un informe con fotografías y presupuestos comparables. Los vecinos comprendieron que retrasar una decisión podía aumentar los costes y los riesgos.","Finalmente aprobaron las obras con una mayoría amplia. La experiencia les enseñó que la prevención y la información transparente protegen mejor a toda una comunidad."]),
    SpanishB2Lesson(unit:2,number:3,title:"A menos que encontremos pruebas",titleAr:"decisiones basadas en datos",grammar:"A menos que + subjuntivo",grammarAr:"إلا إذا وشرط الاستثناء",grammarHelpAr:"نستخدم a menos que + subjuntivo للدلالة على استثناء قد يغيّر قرارًا أو نتيجة.",grammarExamples:<String>["No cambiaremos el plan a menos que surja un problema.","Publicarán el artículo a menos que encuentren errores.","Iré a la reunión a menos que esté enfermo.","No votaremos a menos que tengamos información.","Mantendremos la reserva a menos que la cancelen.","La ayuda continuará a menos que cambie la norma.","No afirmaré nada a menos que existan pruebas.","Aceptaré la propuesta a menos que resulte injusta."],grammarMistakes:<String>["No cambiaremos el plan a menos que surge un problema.","No publicaré a menos que tengo pruebas."],story:<String>["Un grupo de voluntarios planeaba distribuir alimentos a familias con dificultades económicas. Habían recibido una donación importante, pero no disponían de datos actualizados sobre las necesidades de cada zona.","La coordinadora explicó que mantendrían el programa inicial a menos que surgieran pruebas de un reparto desigual. Un compañero propuso consultar directamente a las asociaciones de cada barrio.","Las primeras entrevistas mostraron que algunas familias vivían lejos de los puntos de distribución. Otras necesitaban horarios diferentes porque trabajaban durante el día.","El equipo decidió introducir cambios en el recorrido de entrega y publicar los criterios. También creó un procedimiento para recibir reclamaciones de forma respetuosa y confidencial.","La nueva organización permitió atender mejor a las personas. Los voluntarios aprendieron que una decisión responsable debe mantenerse abierta a nuevas evidencias."]),
    SpanishB2Lesson(unit:2,number:4,title:"Sin que nadie quede fuera",titleAr:"mejorar la convivencia",grammar:"Sin que + subjuntivo",grammarAr:"دون أن يقوم شخص آخر بفعل",grammarHelpAr:"عندما تكون لدينا جملتان بفاعلين مختلفين نستخدم sin que + subjuntivo للدلالة على عدم حدوث فعل.",grammarExamples:<String>["Tomaremos la decisión sin que nadie quede fuera.","Entró sin que los vecinos lo notaran.","Trabajaron sin que el ruido molestara a otros.","Publicaron datos sin que se identificara a nadie.","Llegamos sin que hubiera retrasos.","Organizaron la actividad sin que costara dinero.","La reunión terminó sin que surgieran discusiones.","Explicó la norma sin que nadie se sintiera atacado."],grammarMistakes:<String>["Tomaremos la decisión sin que nadie queda fuera.","Publicaron datos sin que se identifica a nadie."],story:<String>["Una escuela quería organizar un encuentro cultural para estudiantes de diferentes países. El proyecto parecía sencillo, pero varias familias advirtieron de dificultades económicas y de transporte.","La dirección decidió preparar actividades gratuitas para que todos pudieran asistir sin que el coste fuera un obstáculo. También buscó horarios compatibles con distintos compromisos familiares.","Durante los preparativos surgió otra preocupación: algunos estudiantes no se sentían cómodos hablando delante de grupos grandes. Los docentes ofrecieron alternativas para participar por escrito o en equipos pequeños.","El día del encuentro hubo música, fotografías y relatos sobre viajes y tradiciones. Nadie tuvo que representar una cultura entera ni compartir información personal que prefiriera conservar en privado.","Tras la actividad, los organizadores preguntaron qué había funcionado y qué debían mejorar. Comprendieron que la inclusión exige diseñar opciones sin imponer una experiencia idéntica a todos."]),
    SpanishB2Lesson(unit:2,number:5,title:"Actuaba como si lo supiera todo",titleAr:"analizar comportamientos",grammar:"Como si + imperfecto de subjuntivo",grammarAr:"كما لو أن شيئًا غير حقيقي",grammarHelpAr:"نستخدم como si مع imperfecto de subjuntivo لوصف مظهر أو سلوك لا يعكس بالضرورة الحقيقة.",grammarExamples:<String>["Habla como si fuera un experto.","Actuaban como si conocieran todos los hechos.","Me miró como si no me reconociera.","Explicó el informe como si lo hubiera escrito él.","Se comporta como si tuviera razón siempre.","Discutían como si nadie pudiera equivocarse.","Nos recibieron como si fuéramos amigos.","Respondió como si no hubiera oído la pregunta."],grammarMistakes:<String>["Habla como si es un experto.","Actuaban como si conocen todos los hechos."],story:<String>["En una asamblea vecinal, un portavoz presentó una propuesta para transformar una plaza pública. Hablaba con seguridad y utilizaba cifras que nadie había podido consultar antes de la reunión.","Una estudiante de urbanismo observó que el portavoz actuaba como si conociera todas las consecuencias del proyecto. Sin embargo, no explicaba de dónde procedían los presupuestos ni cómo se habían calculado.","La estudiante pidió acceso a las fuentes y formuló preguntas concretas. Algunas personas interpretaron sus dudas como una crítica personal, pero ella insistió en que cuestionaba los datos y no a quien los presentaba.","El portavoz reconoció que varios costes eran aproximados y prometió publicar los cálculos. El debate perdió tensión cuando todos distinguieron entre información confirmada y estimaciones preliminares.","La asamblea decidió estudiar otras alternativas antes de votar. Los participantes comprendieron que hablar con confianza no sustituye la obligación de aportar pruebas."]),
    SpanishB2Lesson(unit:2,number:6,title:"Me alegra que hayáis venido",titleAr:"emociones y evaluaciones",grammar:"Me alegra que + subjuntivo",grammarAr:"المشاعر والتقييم مع المضارع المنصوب",grammarHelpAr:"بعد me alegra que و me preocupa que نستخدم subjuntivo للتعبير عن رد فعل تجاه أمر.",grammarExamples:<String>["Me alegra que hayas venido.","Nos preocupa que falten recursos.","Es una pena que no puedan asistir.","Me sorprende que lo consideren injusto.","Celebro que exista este espacio.","Lamento que algunos se sientan excluidos.","Me encanta que participéis.","Me molesta que no expliquen sus motivos."],grammarMistakes:<String>["Me alegra que has venido.","Nos preocupa que faltan recursos."],story:<String>["Una asociación de familias organizó una jornada para mejorar los servicios de la biblioteca escolar. Quería escuchar tanto a quienes utilizaban el edificio como a quienes apenas lo conocían.","La coordinadora saludó a los asistentes y dijo que le alegraba que hubieran acudido personas tan diferentes. Al mismo tiempo, reconoció que le preocupaba que faltaran representantes de algunos grupos.","Durante el encuentro, varias madres explicaron dificultades relacionadas con el horario. Un estudiante propuso ampliar las actividades y formar un equipo de voluntarios para apoyar a los lectores más jóvenes.","La dirección escuchó las propuestas y acordó realizar una encuesta anónima. La coordinadora insistió en que las emociones eran importantes, pero las decisiones también necesitaban información práctica.","Al despedirse, agradeció la participación y prometió publicar los resultados. Muchos asistentes salieron convencidos de que sus opiniones habían sido escuchadas."]),
    SpanishB2Lesson(unit:2,number:7,title:"Por mucho que lo intentemos",titleAr:"obstáculos que persisten",grammar:"Por mucho que + subjuntivo",grammarAr:"مهما حاولنا مع نتيجة مخالفة",grammarHelpAr:"نستخدم por mucho que + subjuntivo عندما نتحدث عن محاولة محتملة لا تكفي لتغيير النتيجة.",grammarExamples:<String>["Por mucho que estudiemos, siempre habrá dudas.","Por mucho que insistas, no firmaré sin leer.","Por mucho que llueva, continuaremos.","Por mucho que lo intenten, necesitarán ayuda.","Por mucho que explique, algunos no lo aceptarán.","Por mucho que se esfuerce, el plazo es corto.","Por mucho que busquemos, faltan datos.","Por mucho que protesten, deben respetar las normas."],grammarMistakes:<String>["Por mucho que estudiamos, siempre habrá dudas.","Por mucho que insistes, no firmaré."],story:<String>["Un grupo de investigadores colaboraba con una asociación ambiental para limpiar un río. Cada semana retiraban residuos, aunque pronto descubrían nuevos vertidos en diferentes puntos del recorrido.","Una voluntaria comentó que, por mucho que limpiaran, el problema regresaría si no se identificaban sus causas. El equipo decidió investigar las fuentes de contaminación y consultar datos oficiales.","Algunos residentes creían que el problema procedía de una fábrica cercana, pero los análisis no confirmaban esa afirmación. Los investigadores explicaron que acusar sin pruebas podía perjudicar tanto al debate como a las personas afectadas.","La asociación propuso mejorar la recogida de residuos y revisar los sistemas de vigilancia. También organizó talleres para informar a vecinos y comercios sobre hábitos responsables.","El proyecto avanzó lentamente, pero produjo cambios duraderos. Todos comprendieron que resolver problemas complejos exige combinar esfuerzo comunitario y decisiones institucionales."]),
    SpanishB2Lesson(unit:2,number:8,title:"Se vive mejor con buenos servicios",titleAr:"generalizaciones sociales",grammar:"Se impersonal",grammarAr:"التعبير العام عن الناس باستخدام se",grammarHelpAr:"نستخدم se مع فعل في المفرد الثالث عندما نتحدث عن الناس بصورة عامة دون ذكر الفاعل.",grammarExamples:<String>["Se vive bien en este barrio.","Se trabaja mucho aquí.","Se habla español en esta oficina.","No se permite fumar.","Se aprende mejor practicando.","En esa ciudad se conduce con cuidado.","Se puede solicitar información.","Se dice que habrá una reunión."],grammarMistakes:<String>["Se viven bien en este barrio.","Se trabajan mucho aquí impersonalmente."],story:<String>["Dos periodistas prepararon una serie de reportajes sobre la calidad de vida en distintas ciudades. No querían limitarse a comparar precios o fotografías de lugares conocidos.","En cada barrio hablaron con residentes que tenían edades y trabajos diferentes. Descubrieron que se vive de manera distinta según el acceso a transporte, educación y servicios sanitarios.","Uno de los periodistas observó que ciertas estadísticas mostraban promedios engañosos. Una ciudad podía tener una renta alta y, sin embargo, grandes diferencias entre sus habitantes.","El equipo decidió combinar datos oficiales con entrevistas y explicar los límites de cada indicador. Evitaron presentar experiencias individuales como si describieran a toda la población.","La serie terminó con preguntas abiertas sobre las prioridades públicas. Los lectores pudieron comprender que una generalización responsable requiere reconocer la diversidad social."]),
    SpanishB2Lesson(unit:2,number:9,title:"El proyecto fue aprobado",titleAr:"explicar acciones institucionales",grammar:"Pasiva con ser + participio",grammarAr:"المبني للمجهول الرسمي باستخدام ser",grammarHelpAr:"نستخدم ser + participio المتفق مع المبتدأ للتركيز على ما حدث، ويمكن إضافة por لذكر الفاعل.",grammarExamples:<String>["La propuesta fue aprobada por el consejo.","Las obras fueron financiadas por el municipio.","El informe será publicado mañana.","Las decisiones son revisadas cada año.","El edificio fue construido en 1980.","La campaña fue organizada por voluntarios.","Los datos fueron verificados por expertos.","El proyecto había sido rechazado."],grammarMistakes:<String>["La propuesta fue aprobado por el consejo.","Las obras fue financiadas ayer."],story:<String>["El ayuntamiento presentó un proyecto para convertir un edificio vacío en un centro de formación. La iniciativa recibió apoyo de asociaciones y empresas, pero también despertó dudas sobre los costes.","Antes de votar, un equipo técnico revisó la estructura y publicó un presupuesto detallado. Varias propuestas fueron modificadas después de escuchar a vecinos con necesidades diferentes.","El proyecto fue aprobado por el consejo municipal, aunque se incluyeron condiciones de seguimiento. Los responsables prometieron explicar cualquier cambio importante durante las obras.","Durante los meses siguientes se organizaron visitas informativas. Los asistentes comprobaron que algunas salas habían sido adaptadas para facilitar el acceso a personas con discapacidad.","Cuando abrió el centro, los participantes recordaron que ninguna decisión había sido perfecta. Sin embargo, valoraron el esfuerzo por mantener información accesible y responsabilidades claras."]),
    SpanishB2Lesson(unit:2,number:10,title:"El edificio está rehabilitado",titleAr:"describir resultados de acciones",grammar:"Estar + participio",grammarAr:"وصف حالة ناتجة عن فعل باستخدام estar",grammarHelpAr:"نستخدم estar + participio لوصف حالة أو نتيجة حالية، مع التوافق في الجنس والعدد.",grammarExamples:<String>["La sala está preparada.","Los documentos están firmados.","La fachada está restaurada.","La puerta está cerrada.","El informe está terminado.","Las entradas están agotadas.","Los materiales están organizados.","El edificio está rehabilitado."],grammarMistakes:<String>["La sala está preparado.","Los documentos está firmados."],story:<String>["Después de dos años de obras, un centro histórico reabrió sus puertas al público. El edificio estaba restaurado, aunque algunas salas permanecían cerradas para proteger materiales delicados.","La directora explicó que los documentos ya estaban catalogados y que las fotografías estaban disponibles en formato digital. Aun así, parte del archivo necesitaba una revisión especializada.","Los visitantes recorrieron una exposición sobre las transformaciones del barrio. Varias personas mayores reconocieron imágenes de calles que habían cambiado completamente desde su infancia.","Un historiador recordó que restaurar un lugar no significa reconstruir un pasado perfecto. Cada intervención supone decisiones y puede influir en la manera de contar la historia.","Al terminar la visita, la directora anunció futuras actividades. Esperaba que el centro funcionara como un espacio de investigación y encuentro comunitario."]),
    SpanishB2Lesson(unit:3,number:1,title:"En 2030 habremos cambiado",titleAr:"التوقعات المستقبلية",grammar:"Futuro perfecto",grammarAr:"المستقبل التام",grammarHelpAr:"نستخدم haber في المستقبل مع participio لوصف ما سيكتمل قبل موعد مستقبلي.",grammarExamples:<String>["Para 2030 habremos reducido las emisiones.","Mañana habré terminado el informe.","Cuando llegues, ya habrán cerrado.","En un mes habremos comparado los resultados.","¿Habrás leído el estudio para el viernes?","A esa hora, el equipo ya habrá salido.","Dentro de un año habrán instalado el sistema.","Para entonces, habremos aprendido mucho."],grammarMistakes:<String>["Para 2030 habremos reducir las emisiones.","Mañana habré terminando el informe."],story:<String>["Una universidad anunció un proyecto para reducir el consumo energético de sus edificios. Los responsables querían establecer un objetivo cuantificable para los próximos cinco años.","Durante una reunión, varios expertos explicaron que una previsión solo resulta útil si se define un punto de partida. Algunos datos parecían contradictorios.","El equipo instaló sensores para registrar el consumo real y compararlo con las estimaciones anteriores. Una estudiante descubrió que faltaban mediciones en los periodos de vacaciones.","La universidad decidió publicar los criterios de evaluación y reconocer los posibles errores. También organizó talleres para que los usuarios entendieran el funcionamiento del sistema.","Al finalizar el primer año, los investigadores compararon los resultados con sus hipótesis. Comprendieron que mejorar la sostenibilidad exige previsiones prudentes y revisiones periódicas."]),
    SpanishB2Lesson(unit:3,number:2,title:"Serían las diez",titleAr:"تخمينات عن الماضي",grammar:"Condicional simple de probabilidad",grammarAr:"التقدير في الماضي",grammarHelpAr:"نستخدم condicional simple للتعبير عن تخمين غير مؤكد عن وقت أو وضع في الماضي.",grammarExamples:<String>["Serían las diez cuando llamó.","Habría unas veinte personas en la sala.","El informe tendría unas cincuenta páginas.","Entonces ella viviría en otra ciudad.","Serían pocos los que conocían el plan.","¿Qué edad tendría cuando empezó?","La reunión duraría más de una hora.","Probablemente estarían en el laboratorio."],grammarMistakes:<String>["Eran serían las diez cuando llamó.","Habrá unas veinte personas ayer."],story:<String>["Un equipo de historiadores encontró una carta antigua que describía una reunión importante. Sin embargo, el autor no había escrito la fecha completa.","Una investigadora dedujo que serían las diez porque el texto mencionaba el final de la primera clase. Otro historiador señaló que los horarios podían haber cambiado.","Para contrastar la hipótesis, consultaron reglamentos y periódicos de aquella época. Los documentos mostraron que las costumbres eran diferentes según la estación.","Los especialistas prepararon un informe que separaba con claridad los datos comprobados de las interpretaciones probables. Decidieron evitar cifras demasiado precisas.","Durante la exposición, los visitantes comprendieron que una conclusión provisional puede ser valiosa. Reconocer la incertidumbre permite investigar sin inventar respuestas."]),
    SpanishB2Lesson(unit:3,number:3,title:"Debe de haber un error",titleAr:"الاستنتاج والاحتمال",grammar:"Deber de + infinitivo",grammarAr:"الاحتمال باستخدام deber de",grammarHelpAr:"نستخدم deber de مع المصدر للتخمين، ونميزها عن deber دون de التي تستخدم غالبًا للواجب.",grammarExamples:<String>["Debe de haber un error.","Deben de estar revisando los datos.","El sistema debe de funcionar mal.","La conferencia debe de haber comenzado.","Ese gráfico debe de incluir valores antiguos.","Alguien debe de conocer el origen.","La explicación debe de ser incompleta.","Los técnicos deben de estar ocupados."],grammarMistakes:<String>["Debe de estaré trabajando ahora.","El gráfico debe de incluyendo valores antiguos."],story:<String>["Una empresa publicó estadísticas sobre la calidad del aire en varios barrios. Una estudiante observó que algunos valores parecían incompatibles con informes anteriores.","Pensó que debía de haber un error, pero no acusó a nadie de manipulación. Primero revisó las unidades de medida y la explicación metodológica.","Después habló con técnicos independientes y descubrió que un gráfico mezclaba datos de dos periodos. La confusión afectaba a la interpretación de los resultados.","La empresa corrigió la publicación y reconoció su responsabilidad. También estableció un procedimiento para que otros especialistas pudieran revisar las tablas originales.","El caso enseñó a los participantes que sospechar no equivale a demostrar. Una investigación rigurosa empieza formulando hipótesis y buscando pruebas."]),
    SpanishB2Lesson(unit:3,number:4,title:"Llevamos años investigando",titleAr:"نشاط بدأ ويستمر",grammar:"Llevar + gerundio",grammarAr:"مدة استمرار الفعل",grammarHelpAr:"نستخدم llevar مع مدة زمنية وgerundio للتعبير عن نشاط بدأ في الماضي وما زال مستمرًا.",grammarExamples:<String>["Llevamos dos años investigando.","Ella lleva meses estudiando el problema.","¿Cuánto tiempo llevas trabajando aquí?","El equipo lleva semanas comparando fuentes.","Llevan tres días esperando noticias.","Llevo media hora leyendo el informe.","La ciudad lleva años mejorando el transporte.","Llevábamos meses preparando el encuentro."],grammarMistakes:<String>["Llevamos dos años investigar.","Ella lleva meses estudiado el problema."],story:<String>["Una asociación científica llevaba varios años estudiando un río contaminado. Sus voluntarios recogían muestras y registraban los resultados en diferentes estaciones.","Aunque algunas mediciones mostraban mejoras, los investigadores no podían asegurar que el problema estuviera resuelto. El comportamiento del río cambiaba con las lluvias.","Una periodista visitó el laboratorio y preguntó por qué el trabajo continuaba después de tanto tiempo. Una científica le explicó la importancia de observar tendencias.","Durante una reunión, el equipo propuso compartir los datos en un formato accesible. Querían que los vecinos comprendieran tanto los avances como las limitaciones.","El proyecto mostró que un compromiso prolongado produce conocimiento difícil de obtener rápidamente. La paciencia y la transparencia fortalecieron la confianza de la comunidad."]),
    SpanishB2Lesson(unit:3,number:5,title:"Seguimos buscando una solución",titleAr:"الاستمرار رغم الصعوبات",grammar:"Seguir + gerundio",grammarAr:"مواصلة الفعل",grammarHelpAr:"نستخدم seguir مع gerundio للدلالة على استمرار النشاط رغم العقبات أو التغيرات.",grammarExamples:<String>["Seguimos buscando una solución.","El equipo sigue revisando los datos.","¿Sigues trabajando en el proyecto?","La ciudad sigue invirtiendo en transporte.","Aún seguimos esperando la respuesta.","Los expertos siguieron comparando alternativas.","Ella continúa investigando el origen.","Los vecinos siguen participando."],grammarMistakes:<String>["Seguimos buscar una solución.","El equipo sigue revisado los datos."],story:<String>["Un instituto técnico quería mejorar la conexión a internet en zonas rurales. El primer proyecto resultó demasiado caro y no alcanzaba a todas las familias.","Los responsables siguieron buscando alternativas y consultaron a especialistas de otras regiones. También escucharon a estudiantes que dependían de la conexión para aprender.","Una nueva tecnología ofrecía mejores resultados, pero exigía mantenimiento y formación. Los expertos propusieron una prueba pequeña antes de ampliar la inversión.","Los vecinos participaron en la evaluación y comunicaron dificultades que los informes técnicos no habían previsto. El equipo modificó el diseño de acuerdo con esos datos.","La iniciativa avanzó lentamente, pero permitió ofrecer un servicio más estable. Sus participantes entendieron que perseverar también implica cambiar de estrategia."]),
    SpanishB2Lesson(unit:3,number:6,title:"Acaban de publicar el informe",titleAr:"خبر وقع للتو",grammar:"Acabar de + infinitivo",grammarAr:"التعبير عن الحدث الحديث",grammarHelpAr:"نستخدم acabar de + infinitivo في المضارع لوصف أمر حصل للتو أو منذ وقت قصير جدًا.",grammarExamples:<String>["Acaban de publicar el informe.","Acabo de recibir los datos.","La investigadora acaba de llegar.","Acabamos de terminar la evaluación.","¿Acabas de ver el anuncio?","El equipo acaba de detectar un problema.","Los responsables acaban de responder.","Acaban de instalar el sistema."],grammarMistakes:<String>["Acaban de publicando el informe.","Acabo de recibido los datos."],story:<String>["Una universidad acababa de publicar un estudio sobre el transporte urbano. Los primeros titulares llamaron la atención por presentar diferencias importantes entre barrios.","Varios estudiantes leyeron el documento completo y descubrieron que algunas noticias simplificaban demasiado los resultados. Los autores habían señalado límites metodológicos relevantes.","Los investigadores compararon precios, tiempos y accesibilidad de las rutas. Aun así, reconocieron que los indicadores no describían todas las experiencias personales.","Durante una conferencia pública, los participantes plantearon preguntas sobre el origen de las cifras. El equipo ofreció enlaces para consultar los datos y revisar las conclusiones.","Los estudiantes prepararon una explicación para su comunidad. Querían que las personas discutieran las propuestas utilizando información verificada, no solamente titulares."]),
    SpanishB2Lesson(unit:3,number:7,title:"Tan complejo que necesitó ayuda",titleAr:"النتيجة الناتجة عن درجة",grammar:"Tan ... que",grammarAr:"التعبير عن نتيجة شديدة",grammarHelpAr:"نستخدم tan + صفة أو حال + que لربط شدة صفة بالنتيجة التي تسببها.",grammarExamples:<String>["El problema era tan complejo que pidió ayuda.","La explicación fue tan clara que todos entendieron.","El cambio fue tan rápido que sorprendió.","El sistema era tan caro que lo descartaron.","La reunión fue tan larga que terminó tarde.","El gráfico resultó tan confuso que lo revisaron.","Fue tan útil que repetimos el taller.","El plan era tan ambicioso que necesitó más recursos."],grammarMistakes:<String>["El problema era tan complejo como pidió ayuda.","La explicación fue tan clara de que todos entendieron."],story:<String>["Un ayuntamiento intentó desarrollar una plataforma para gestionar citas médicas en varios centros. La propuesta parecía útil, pero implicaba requisitos técnicos complejos.","Los funcionarios descubrieron que la integración era tan difícil que necesitaron asesoramiento independiente. Algunas empresas ofrecían soluciones rápidas sin explicar todos los costes.","La comisión organizó demostraciones y comparó la accesibilidad de los sistemas. Una enfermera recordó que muchos usuarios también necesitaban atención presencial.","Finalmente eligieron una plataforma sencilla y planificaron un lanzamiento gradual. Durante las pruebas aparecieron errores que pudieron corregirse antes de afectar a más personas.","El proyecto enseñó que una innovación debe evaluarse según sus resultados reales. La tecnología más llamativa no siempre es la opción más adecuada."]),
    SpanishB2Lesson(unit:3,number:8,title:"No solo ahorra, sino que mejora",titleAr:"إضافة حجة ثانية",grammar:"No solo ... sino también",grammarAr:"التأكيد على فائدتين",grammarHelpAr:"نستخدم no solo ... sino también لإضافة فائدة أخرى، ومع الأفعال نقول sino que también.",grammarExamples:<String>["El sistema no solo ahorra energía, sino que también reduce costes.","No solo estudia, sino que también trabaja.","La iniciativa beneficia no solo a jóvenes, sino también a mayores.","No solo mejoramos el transporte, sino también la seguridad.","No solo es fiable, sino también accesible.","La campaña no solo informa, sino que también motiva.","No solo revisaron cifras, sino que contrastaron testimonios.","El proyecto no solo crea empleo, sino que impulsa la formación."],grammarMistakes:<String>["El sistema no solo ahorra energía, pero también reduce costes.","No solo estudia, sino también trabaja."],story:<String>["Una cooperativa diseñó un programa para mejorar la eficiencia energética de viviendas antiguas. Su objetivo era reducir los gastos y ayudar a familias con pocos recursos.","La propuesta incluía asesoramiento técnico y materiales duraderos. Durante las primeras visitas, los ingenieros detectaron problemas que no figuraban en el proyecto inicial.","Una especialista explicó que la iniciativa no solo ahorraría energía, sino que también podría mejorar la salud y la comodidad de los residentes.","Los responsables publicaron resultados positivos y dificultades inesperadas. Rechazaron presentar el programa como una solución universal, porque los edificios tenían necesidades diferentes.","Al terminar el año, ampliaron gradualmente las actividades. Los vecinos valoraron la combinación de beneficios económicos, ambientales y sociales."]),
    SpanishB2Lesson(unit:3,number:9,title:"A pesar de conocer los riesgos",titleAr:"التناقض مع المصدر",grammar:"A pesar de + infinitivo",grammarAr:"رغم فعل شيء",grammarHelpAr:"نستخدم a pesar de مع المصدر لذكر عقبة أو سبب مخالف عندما يكون فاعل الفعل واحدًا.",grammarExamples:<String>["A pesar de conocer los riesgos, continuó.","A pesar de tener dudas, participamos.","A pesar de trabajar mucho, escucha a todos.","A pesar de disponer de datos, pidió más pruebas.","A pesar de llegar tarde, pudo intervenir.","A pesar de ser difícil, intentaremos resolverlo.","A pesar de no contar con fondos, organizaron el taller.","A pesar de haber estudiado, necesitó ayuda."],grammarMistakes:<String>["A pesar de conozco los riesgos, continué.","A pesar de que conocer los riesgos, siguió."],story:<String>["Una investigadora recibió una invitación para evaluar un proyecto de inteligencia artificial. Le interesaba la tecnología, pero conocía los riesgos relacionados con los datos personales.","A pesar de esas preocupaciones, aceptó colaborar con la condición de que se publicaran los métodos. También solicitó una revisión independiente.","Las primeras pruebas mostraron mejoras, aunque algunos usuarios recibían resultados menos fiables. La investigadora insistió en documentar las diferencias antes del lanzamiento.","Varios directivos defendieron la publicación inmediata. Ella explicó que aplazar una decisión puede ser responsable si todavía faltan garantías importantes.","El equipo aceptó ampliar la evaluación y escuchar nuevas perspectivas. Reconocer los riesgos permitió mejorar el sistema sin rechazar toda innovación."]),
    SpanishB2Lesson(unit:3,number:10,title:"Los datos son útiles; no obstante...",titleAr:"الاعتراض الرسمي",grammar:"No obstante como conector",grammarAr:"عرض تحفظ في نقاش",grammarHelpAr:"نستخدم no obstante في بداية جملة أو بين فواصل لتقديم ملاحظة مخالفة لما سبق.",grammarExamples:<String>["Los datos son útiles; no obstante, son incompletos.","La idea es atractiva. No obstante, necesita pruebas.","El presupuesto ha mejorado; no obstante, hay riesgos.","El estudio es reciente; no obstante, la muestra es pequeña.","Hay avances. No obstante, debemos escuchar críticas.","Fue un proceso largo; no obstante, aprendimos mucho.","El informe parece sólido. No obstante, falta una fuente.","La propuesta beneficia al barrio; no obstante, exige recursos."],grammarMistakes:<String>["Los datos son útiles; no obstante porque son incompletos.","No obstante de la idea es atractiva, necesita pruebas."],story:<String>["Una comisión evaluó proyectos para mejorar la movilidad de una ciudad. Las propuestas incluían gráficos, encuestas y diferentes estimaciones de inversión.","Varios estudios mostraban beneficios de ampliar el transporte público. No obstante, algunos informes no explicaban qué ocurriría en los barrios más alejados.","Una representante vecinal pidió que se midieran también los desplazamientos de personas mayores. Un técnico reconoció que aquel indicador no había sido incluido.","La comisión decidió solicitar una evaluación complementaria. Aclaró que no rechazaba todas las propuestas, sino que necesitaba criterios comparables y transparentes.","Al publicar sus conclusiones, explicó los puntos fuertes y las dudas pendientes. El debate mostró que reconocer avances no impide señalar limitaciones."]),
  ];
  static SpanishB2Lesson find(int unit,int number)=>lessons.firstWhere(
      (x)=>x.unit==unit&&x.number==number);
  static List<String> grammarOptions(SpanishB2Lesson lesson)=>
      <String>[lesson.grammarMistakes.first,lesson.grammarExamples.first,
        lesson.grammarMistakes.last];

  /// Original five authored paragraphs + a sixth, contextual word review.
  /// The review is separate from the main story to avoid forced word insertion.
  static List<String> reading(SpanishB2Lesson lesson){
    final n=wordsOf(lesson,SpanishWordKind.noun);
    final v=wordsOf(lesson,SpanishWordKind.verb);
    final a=wordsOf(lesson,SpanishWordKind.adjective);
    final d=wordsOf(lesson,SpanishWordKind.adverb);
    return <String>[
      ...lesson.story,
      'Tras la experiencia, el equipo volvió a reunirse para debatir las '
      'consecuencias de sus decisiones. Tomaron notas de dos conceptos '
      'relevantes, «${n[0].es}» y «${n[1].es}», y analizaron cómo '
      'podían aplicar «${v[0].es}» y «${v[1].es}» a la situación descrita. '
      'También discutieron si las expresiones «${a[0].es}» y '
      '«${a[1].es}» representaban realmente los hechos. '
      'En su conclusión, citaron «${d[0].es}» y «${d[1].es}» '
      'como recursos lingüísticos que conviene utilizar con precisión. '
      'Finalmente defendieron una postura razonada, reconocieron sus '
      'limitaciones y formularon preguntas para una investigación futura.',
    ];
  }

  static List<String> conversation(SpanishB2Lesson lesson){
    final n=wordsOf(lesson,SpanishWordKind.noun);
    final v=wordsOf(lesson,SpanishWordKind.verb);
    final a=wordsOf(lesson,SpanishWordKind.adjective);
    final d=wordsOf(lesson,SpanishWordKind.adverb);
    return <String>[
      'Lucía: ¿Qué implicaciones tiene el tema «${lesson.title}»?',
      'Diego: La «${n[0].es}» es fundamental, aunque la «${n[1].es}» '
          'también merece atención.',
      'Lucía: ¿Qué datos necesitaríamos para defender esa interpretación?',
      'Diego: Primero deberíamos ${v[0].es} ${d[0].es}; después podríamos '
          '${v[1].es} ${d[1].es}.',
      'Lucía: Sin embargo, ¿no podría resultar ${a[0].es} esa conclusión?',
      'Diego: Es posible que sí; debemos distinguir una explicación '
          '${a[1].es} de una mera suposición.',
      'Lucía: ¿Cómo resumirías tu postura sin ignorar las objeciones?',
      'Diego: Aceptaría el argumento provisionalmente y explicaría '
          'qué pruebas podrían hacerme reconsiderarlo.',
    ];
  }
  static String podcast(SpanishB2Lesson lesson){
    final groups=SpanishWordKind.values.map((kind){
      final name=switch(kind){
        SpanishWordKind.noun=>'sustantivos',
        SpanishWordKind.verb=>'verbos',
        SpanishWordKind.adjective=>'adjetivos',
        SpanishWordKind.adverb=>'adverbios',
      };
      final terms=wordsOf(lesson,kind).map((w)=>w.es).join(', ');
      return 'Escucha los diez $name: $terms. ';
    }).join();
    return 'Bienvenidos al pódcast de español B2 de WorldVoice. '
        'Hoy examinaremos un relato titulado ${lesson.title}. '
        '${lesson.story.join(' ')} '
        'A continuación, repasaremos las cuarenta palabras del tema. '
        '$groups'
        'Escucha otra vez y distingue los hechos de las opiniones. '
        'Formula un argumento y un contraargumento utilizando la regla '
        'gramatical ${lesson.grammar}. Señala qué datos respaldan '
        'tu conclusión y cuáles siguen siendo inciertos.';
  }
}
